def move_audio_to_private_storage(apps, schema_editor):
    """Recordings uploaded before this migration sit in MEDIA_ROOT (public /media/): move them to the private
    storage, under the same name, so that only GET /api/meetings/<id>/audio/ serves them."""
    import os
    import shutil

    Meeting = apps.get_model("meetings", "Meeting")
    for name in Meeting.objects.exclude(audio_file="").values_list("audio_file", flat=True):
        source = os.path.join(settings.MEDIA_ROOT, name)
        target = os.path.join(settings.MEETINGS_AUDIO_ROOT, name)
        if os.path.isfile(source) and not os.path.exists(target):
            os.makedirs(os.path.dirname(target), exist_ok=True)
            shutil.move(source, target)


